    "sets.heroSubtitle": "Познакомьтесь с восточными ароматами перед покупкой полного флакона: открывайте миниатюры, отливанты и пробники от 1 мл, 2 мл, 5 мл, 10 мл, а также эксклюзивные подарочные и дискавери-сеты.",
