    "about.statLongevity": "Стойкость селективных композиций",
    "about.statLongevityVal": "12–16 ч",
    "about.statDeliveryVal": "4–7 дней",
    "about.storySec": "ИСТОРИЯ И ФИЛОСОФИЯ БРЕНДА",
    "about.storyTitle": "Наследие Ближнего Востока в каждой капле",
    "about.storyP1": "Восточная парфюмерия — это больше, чем просто аромат. Это ритуал гостеприимства, выражение индивидуальности и невидимая корона, которая сопровождает вас на протяжении всего дня. В отличие от массовой парфюмерии, композиции с Ближнего Востока создаются на основе высокой концентрации натуральных масел, редких смол и благородной древесины.",
    "about.storyP2": "В коллекции Al-Warda собраны знаковые бестселлеры и редкие нишевые жемчужины от ведущих парфюмерных домов Ближнего Востока. Мы тщательно отбираем каждый аромат, проверяем подлинность партий и гарантируем безупречное состояние каждого флакона.",
    "about.valuesSec": "ЦЕННОСТИ ДОМА AL-WARDA",
    "about.pillar1Title": "100% Подлинность",
    "about.pillar1Desc": "Прямые поставки от сертифицированных парфюмерных домов Ближнего Востока. Каждый флакон поставляется в заводской упаковке с голограммами и батч-кодом.",
    "about.pillar2Title": "Драгоценные Масла и Стойкость",
    "about.pillar2Desc": "Высокая концентрация натуральных эфирных масел (Eau de Parfum и Extrait de Parfum) обеспечивает стойкость от 10 до 16 часов и глубокий, благородный шлейф.",
    "about.pillar3Title": "Эксклюзивные Сеты",
    "about.pillar3Desc": "Роскошные подарочные наборы и дискавери-коллекции в дизайнерских шкатулках — безупречный выбор для знакомства с нишевой парфюмерией или статусного подарка.",
    "about.pillar4Title": "Парфюмерный Консьерж Ясмин",
    "about.pillar4Desc": "Персональный ИИ-консультант Ясмин мгновенно подберёт идеальный парфюм по вашим любимым нотам, времени года, поводу и предпочтениям.",
    "about.notesSec": "ДРАГОЦЕННЫЕ НОТЫ И ИНГРЕДИЕНТЫ",
    "about.ing1Name": "Королевский Уд",
    "about.ing1Role": "Сердце восточной традиции",
    "about.ing1Desc": "Драгоценная смолистая древесина агарового дерева придаёт композициям гипнотическую глубину, бархатный дымный оттенок и неповторимый статус.",
    "about.ing2Name": "Дамасская и Таифская Роза",
    "about.ing2Role": "Символ дома Al-Warda",
    "about.ing2Desc": "«Аль-Варда» в переводе с арабского означает «Роза». Собранные на рассвете лепестки дарят ароматам чувственную медово-цветочную грань.",
    "about.ing3Name": "Золотая Амбра и Мускус",
    "about.ing3Role": "Магнетизм и тёплый шлейф",
    "about.ing3Desc": "Солнечные амбровые аккорды в сочетании с шелковистым белым мускусом создают на коже тёплое, притягательное и обволакивающее послевкусие.",
    "about.ing4Name": "Шафран, Кардамон и Ваниль",
    "about.ing4Role": "Пряная гурманика Востока",
    "about.ing4Desc": "Благородные специи в дуэте с мадагаскарской ванилью, пралине и бобами тонка рождают комплиментарные, многогранные композиции.",
    "about.housesSec": "ИЗБРАННЫЕ ПАРФЮМЕРНЫЕ ДОМА",
    "contacts.developer": "Девелопер",
    "contacts.phoneDesc": "Звонки и сообщения WhatsApp / Viber",
