    "footer.brandDesc": "Дом эксклюзивной арабской парфюмерии. Оригинальные селективные ароматы прямиком из парфюмерных мануфактур Ближнего Востока: редчайший уд, дамасская роза, золотая амбра и чувственный мускус.",
