    "about.statLongevity": "Signature Fragrance Longevity",
    "about.statLongevityVal": "12–16 hrs",
    "about.statDeliveryVal": "4–7 days",
    "about.storySec": "HERITAGE & PHILOSOPHY",
    "about.storyTitle": "Middle Eastern Heritage in Every Drop",
    "about.storyP1": "Middle Eastern perfumery is far more than a scent — it is a ritual of hospitality, an expression of identity, and an invisible crown that accompanies you throughout the day. Unlike mass-market fragrances, creations from the Middle East are formulated with rich concentrations of natural oils, rare resins, and noble woods.",
    "about.storyP2": "The Al-Warda collection unites iconic bestsellers and rare niche gems from the premier perfume houses of the Middle East. We curate every composition with care, verify batch authenticity, and guarantee pristine presentation in every bottle.",
    "about.valuesSec": "THE AL-WARDA PROMISE",
    "about.pillar1Title": "100% Authenticity",
    "about.pillar1Desc": "Direct supply from certified perfume houses of the Middle East. Every flacon arrives factory-sealed with original holograms and batch codes.",
    "about.pillar2Title": "Precious Oils & Longevity",
    "about.pillar2Desc": "High concentrations of natural essential oils (Eau de Parfum and Extrait de Parfum) deliver 10 to 16 hours of longevity and a majestic sillage.",
    "about.pillar3Title": "Luxury Gift Sets",
    "about.pillar3Desc": "Opulent gift coffrets and discovery collections in signature presentation boxes — an impeccable choice for exploring niche scents or gifting.",
    "about.pillar4Title": "Yasmin AI Fragrance Concierge",
    "about.pillar4Desc": "Our personal AI consultant Yasmin curates your ideal fragrance based on your favorite olfactory notes, season, occasion, and style.",
    "about.notesSec": "PRECIOUS OLFACTORY INGREDIENTS",
    "about.ing1Name": "Royal Agarwood (Oud)",
    "about.ing1Role": "Heart of Middle Eastern Heritage",
    "about.ing1Desc": "Precious resinous heartwood that lends fragrances a hypnotic depth, velvety smoky warmth, and unmistakable sophistication.",
    "about.ing2Name": "Damask & Taif Rose",
    "about.ing2Role": "Emblem of the House of Al-Warda",
    "about.ing2Desc": "'Al-Warda' translates from Arabic as 'The Rose'. Hand-picked at dawn, its petals infuse creations with a sensual, honeyed floral radiance.",
    "about.ing3Name": "Golden Amber & White Musk",
    "about.ing3Role": "Magnetism & Warm Sillage",
    "about.ing3Desc": "Solar amber accords intertwined with silky white musk create an enveloping, skin-warming trail that lingers from morning till night.",
    "about.ing4Name": "Saffron, Cardamom & Vanilla",
    "about.ing4Role": "Opulent Oriental Spices",
    "about.ing4Desc": "Noble spices paired with Madagascar vanilla, praline, and tonka bean craft multifaceted, compliment-inducing signatures.",
    "about.housesSec": "FEATURED PERFUME HOUSES",
