    "about.statLongevity": "A válogatott kompozíciók tartóssága",
    "about.statLongevityVal": "12–16 óra",
    "about.statDeliveryVal": "4–7 nap",
    "about.storySec": "A MÁRKA TÖRTÉNETE ÉS FILOZÓFIÁJA",
    "about.storyTitle": "A Közel-Kelet öröksége minden cseppben",
    "about.storyP1": "A keleti parfümkészítés több mint illat — a vendégszeretet rituáléja, az egyéniség kifejezése és egy láthatatlan korona, amely egész nap elkíséri Önt. A tömegtermékekkel ellentétben a közel-keleti kompozíciók természetes olajok, ritka gyanták és nemes fák gazdag koncentrációjával készülnek.",
    "about.storyP2": "Az Al-Warda kollekció ikonikus bestsellereket és ritka réspiaci kincseket egyesít a Közel-Kelet vezető parfümházaiból. Minden kompozíciót gondosan válogatunk, ellenőrizzük a tételek hitelességét és garantáljuk a hibátlan megjelenést.",
    "about.valuesSec": "AZ AL-WARDA HÁZ ÉRTÉKEI",
    "about.pillar1Title": "100% Eredetiség",
    "about.pillar1Desc": "Közvetlen szállítás a Közel-Kelet minősített parfümházaiból. Minden üveg gyári csomagolásban érkezik eredeti hologramokkal és gyártási kóddal.",
    "about.pillar2Title": "Értékes Olajok és Tartósság",
    "about.pillar2Desc": "A természetes illóolajok magas koncentrációja (Eau de Parfum és Extrait de Parfum) 10-16 órás tartósságot és mély, fenséges aurát biztosít.",
    "about.pillar3Title": "Exkluzív Készletek",
    "about.pillar3Desc": "Pompás ajándékkészletek és felfedező kollekciók díszdobozokban — kifogástalan választás a réspiaci illatok megismeréséhez vagy rangos ajándéknak.",
    "about.pillar4Title": "Jázmin AI Parfüm Concierge",
    "about.pillar4Desc": "Személyes AI tanácsadónk, Jázmin azonnal kiválasztja az ideális illatot kedvenc jegyei, évszak, alkalom és stílus szerint.",
    "about.notesSec": "ÉRTÉKES ILLATJEGYEK ÉS ÖSSZETEVŐK",
    "about.ing1Name": "Királyi Agárfa (Oud)",
    "about.ing1Role": "A keleti hagyomány szíve",
    "about.ing1Desc": "Értékes gyantás agárfa, amely hipnotikus mélységet, bársonyos füstös melegséget és összetéveszthetetlen kifinomultságot kölcsönöz az illatoknak.",
    "about.ing2Name": "Damaszkuszi és Taif Rózsa",
    "about.ing2Role": "Az Al-Warda Ház szimbóluma",
    "about.ing2Desc": "Az 'Al-Warda' arabul 'A Rózsa' jelentésű. A hajnalban kézzel szedett szirmok érzéki, mézes virágos ragyogással gazdagítják a kreációkat.",
    "about.ing3Name": "Arany Borostyán és Fehér Pézsma",
    "about.ing3Role": "Mágnesesség és meleg aura",
    "about.ing3Desc": "A napfényes borostyán akkordok a selymes fehér pézsmával összefonódva meleg, vonzó és körülölelő nyomot hagynak a bőrön.",
    "about.ing4Name": "Sáfrány, Kardamom és Vanília",
    "about.ing4Role": "Pompás keleti fűszerek",
    "about.ing4Desc": "A nemes fűszerek a madagaszkári vaníliával, pralinéval és tonkababbal párosítva sokoldalú, elismerést arató illatjegyeket alkotnak.",
    "about.housesSec": "KIEMELT PARFÜMHÁZAK",
