    "about.statLongevity": "Дълготрайност на селективните композиции",
    "about.statLongevityVal": "12–16 ч",
    "about.statDeliveryVal": "4–7 дни",
    "about.storySec": "ИСТОРИЯ И ФИЛОСОФИЯ НА БРАНДА",
    "about.storyTitle": "Наследството на Близкия изток във всяка капка",
    "about.storyP1": "Ориенталската парфюмерия е нещо много повече от аромат. Това е ритуал на гостоприемство, израз на индивидуалност и невидима корона, която ви съпътства през целия ден. За разлика от масовата парфюмерия, композициите от Близкия изток се създават с висока концентрация на натурални масла, редки смоли и благородна дървесина.",
    "about.storyP2": "В колекцията на Al-Warda са събрани емблематични бестселъри и редки нишови бижута от водещите парфюмерийни къщи на Близкия изток. Подбираме грижливо всеки аромат, проверяваме автентичността на партидите и гарантираме безупречно качество.",
    "about.valuesSec": "ЦЕННОСТИТЕ НА ДОМ AL-WARDA",
    "about.pillar1Title": "100% Автентичност",
    "about.pillar1Desc": "Директни доставки от сертифицирани парфюмерийни къщи от Близкия изток. Всеки флакон се доставя във фабрична опаковка с холограми и партиден код.",
    "about.pillar2Title": "Драгоценни Масла и Дълготрайност",
    "about.pillar2Desc": "Високата концентрация на естествени етерични масла осигурява трайност от 10 до 16 часа и богат, благороден шлейф.",
    "about.pillar3Title": "Ексклузивни Комплекти",
    "about.pillar3Desc": "Луксозни подаръчни сетове и дискавъри колекции в дизайнерски кутии — безупречен избор за запознаване с нишовата парфюмерия или за престижен подарък.",
    "about.pillar4Title": "Парфюмериен Консиерж Ясмин",
    "about.pillar4Desc": "Персоналният AI консултант Ясмин мигновено ще подбере идеалния аромат според любимите ви нотки, сезона, повода и стила.",
    "about.notesSec": "ДРАГОЦЕННИ НОТКИ И СЪСТАВКИ",
    "about.ing1Name": "Кралски Уд",
    "about.ing1Role": "Сърцето на ориенталската традиция",
    "about.ing1Desc": "Ценна смолиста дървесина, която придава на ароматите хипнотична дълбочина, кадифена опушена топлота и неповторим престиж.",
    "about.ing2Name": "Дамаска и Таифска Роза",
    "about.ing2Role": "Символ на дом Al-Warda",
    "about.ing2Desc": "„Ал-Варда“ в превод от арабски означава „Роза“. Събраните в зори листенца даряват ароматите с чувствено медено-флорално излъчване.",
    "about.ing3Name": "Златен Кехлибар и Бял Мускус",
    "about.ing3Role": "Магнетизъм и топъл шлейф",
    "about.ing3Desc": "Слънчевите кехлибарени акорди в съчетание с копринения бял мускус оставят топла, притегателна и обгръщаща следа върху кожата.",
    "about.ing4Name": "Шафран, Кардамон и Ванилия",
    "about.ing4Role": "Ориенталски пикантни изкушения",
    "about.ing4Desc": "Благородните подправки в дует с мадагаскарска ванилия, пралине и тонка боб създават многопластови и завладяващи композиции.",
    "about.housesSec": "ИЗБРАНИ ПАРФЮМЕРИЙНИ КЪЩИ",
