    "about.storySec": "ΙΣΤΟΡΙΑ & ΦΙΛΟΣΟΦΙΑ ΤΟΥ ΟΙΚΟΥ",
    "about.storyTitle": "Η κληρονομιά της Μέσης Ανατολής σε κάθε σταγόνα",
    "about.storyP1": "Η ανατολίτικη αρωματοποιία είναι κάτι πολύ περισσότερο από ένα άρωμα. Είναι τελετουργικό φιλοξενίας, έκφραση προσωπικότητας και ένα αόρατο στέμμα που σας συνοδεύει όλη την ημέρα. Σε αντίθεση με τα αρώματα μαζικής παραγωγής, οι δημιουργίες της Μέσης Ανατολής παρασκευάζονται με υψηλή συγκέντρωση φυσικών ελαίων, σπάνιων ρητινών και ευγενών ξύλων.",
    "about.storyP2": "Η συλλογή Al-Warda συγκεντρώνει εμβληματικά bestsellers και σπάνια διαμάντια niche από τους κορυφαίους οίκους αρωμάτων της Μέσης Ανατολής. Επιλέγουμε προσεκτικά κάθε άρωμα, πιστοποιούμε την αυθεντικότητα των παρτίδων και εγγυόμαστε άψογη ποιότητα σε κάθε μπουκάλι.",
    "about.valuesSec": "ΟΙ ΑΞΙΕΣ ΤΟΥ ΟΙΚΟΥ AL-WARDA",
    "about.pillar1Title": "100% Αυθεντικότητα",
    "about.pillar1Desc": "Απευθείας προμήθειες από πιστοποιημένους οίκους της Μέσης Ανατολής. Κάθε φιάλη παραδίδεται σε εργοστασιακή συσκευασία με ολογράμματα και batch code.",
    "about.pillar2Title": "Πολύτιμα Έλαια & Διάρκεια",
    "about.pillar2Desc": "Η υψηλή συγκέντρωση φυσικών αιθέριων ελαίων εξασφαλίζει διάρκεια από 10 έως 16 ώρες και βαθύ, αριστοκρατικό ίχνος.",
    "about.pillar3Title": "Αποκλειστικά Σετ",
    "about.pillar3Desc": "Πολυτελή σετ δώρου και συλλογές discovery σε επώνυμες κασετίνες — άψογη επιλογή για γνωριμία με τα niche αρώματα ή για ένα ξεχωριστό δώρο.",
    "about.pillar4Title": "Yasmin AI Fragrance Concierge",
    "about.pillar4Desc": "Η προσωπική σύμβουλος AI Yasmin επιλέγει το ιδανικό άρωμα με βάση τις αγαπημένες σας νότες, την εποχή, την περίσταση και το στυλ.",
    "about.notesSec": "ΠΟΛΥΤΙΜΕΣ ΟΣΦΡΗΤΙΚΕΣ ΝΟΤΕΣ & ΣΥΣΤΑΤΙΚΑ",
    "about.ing1Name": "Βασιλικό Ούντ",
    "about.ing1Role": "Η καρδιά της ανατολίτικης κληρονομιάς",
    "about.ing1Desc": "Πολύτιμο ρητινώδες ξύλο που προσδίδει στα αρώματα υπνωτικό βάθος, βελούδινη καπνιστή ζεστασιά και απαράμιλλη κομψότητα.",
    "about.ing2Name": "Τριαντάφυλλο Δαμασκού & Ταΐφ",
    "about.ing2Role": "Έμβλημα του Οίκου Al-Warda",
    "about.ing2Desc": "Το 'Al-Warda' σημαίνει στα αραβικά 'Το Τριαντάφυλλο'. Μαζεμένα στην αυγή, τα πέταλά του εμπλουτίζουν τις δημιουργίες με αισθησιακή ανθοφορία.",
    "about.ing3Name": "Χρυσό Κεχριμπάρι & Λευκός Μόσχος",
    "about.ing3Role": "Μαγνητισμός & Ζεστό Ίχνος",
    "about.ing3Desc": "Οι ηλιόλουστες κεχριμπαρένιες νότες σε αρμονία με τον μεταξένιο λευκό μόσχο δημιουργούν ένα ζεστό, σαγηνευτικό αποτύπωμα στο δέρμα.",
    "about.ing4Name": "Σαφράν, Καρδάμωμο & Βανίλια",
    "about.ing4Role": "Πλούσια ανατολίτικα μπαχαρικά",
    "about.ing4Desc": "Ευγενή μπαχαρικά σε συνδυασμό με βανίλια Μαδαγασκάρης, πραλίνα και κόκκους τόνκα συνθέτουν πολυδιάστατες υπογραφές.",
