    "about.statLongevity": "Persistența compozițiilor de nișă",
    "about.statLongevityVal": "12–16 ore",
    "about.statDeliveryVal": "4–7 zile",
    "about.storySec": "ISTORIA ȘI FILOZOFIA BRANDULUI",
    "about.storyTitle": "Moștenirea Orientului Mijlociu în fiecare picătură",
    "about.storyP1": "Parfumeria orientală înseamnă mult mai mult decât o mireasmă. Este un ritual al ospitalității, o expresie a individualității și o coroană invizibilă care vă însoțește pe tot parcursul zilei. Spre deosebire de parfumeria de masă, creațiile din Orientul Mijlociu sunt formulate cu concentrații bogate de uleiuri naturale, rășini rare și lemne nobile.",
    "about.storyP2": "Colecția Al-Warda reunește bestselleruri emblematice și nestemate de nișă rare de la cele mai apreciate case de parfumuri din Orientul Mijlociu. Selectăm cu grijă fiecare compoziție, verificăm autenticitatea loturilor și garantăm calitatea impecabilă a fiecărei sticle.",
    "about.valuesSec": "VALORILE CASEI AL-WARDA",
    "about.pillar1Title": "100% Autenticitate",
    "about.pillar1Desc": "Livrări directe de la case de parfumuri certificate din Orientul Mijlociu. Fiecare sticlă vine în ambalaj de fabrică sigilat cu holograme originale și cod de lot.",
    "about.pillar2Title": "Uleiuri Prețioase și Persistență",
    "about.pillar2Desc": "Concentrația ridicată de uleiuri esențiale naturale asigură o persistență de la 10 la 16 ore și un siaj profund, maiestuos.",
    "about.pillar3Title": "Seturi Exclusive",
    "about.pillar3Desc": "Casete de cadou somptuoase și colecții de descoperire în cutii de prezentare rafinate — o alegere impecabilă pentru explorarea parfumurilor de nișă sau pentru un cadou de prestigiu.",
    "about.pillar4Title": "Concierge de Parfumuri AI Yasmin",
    "about.pillar4Desc": "Consultantul personal AI Yasmin selectează parfumul ideal pe baza notelor preferate, a sezonului, ocaziei și stilului dumneavoastră.",
    "about.notesSec": "NOTE ȘI INGREDIENTE OLFACTIVE PREȚIOASE",
    "about.ing1Name": "Oud Regal",
    "about.ing1Role": "Inima tradiției orientale",
    "about.ing1Desc": "Lemn rășinos prețios care conferă parfumurilor o profunzime hipnotică, o căldură catifelată și o sofisticare inconfundabilă.",
    "about.ing2Name": "Trandafir de Damasc și Taif",
    "about.ing2Role": "Emblema Casei Al-Warda",
    "about.ing2Desc": "„Al-Warda” se traduce din arabă prin „Trandafirul”. Culese în zori, petalele sale îmbogățesc compozițiile cu o strălucire florală senzuală.",
    "about.ing3Name": "Ambră Aurie și Mosc Alb",
    "about.ing3Role": "Magnetism și siaj cald",
    "about.ing3Desc": "Acordurile solare de ambră împletite cu moscul alb mătăsos creează o urmă învăluitoare și caldă pe piele de dimineața până seara.",
    "about.ing4Name": "Șofran, Cardamom și Vanilie",
    "about.ing4Role": "Condimente orientale somptuoase",
    "about.ing4Desc": "Condimentele nobile alături de vanilia de Madagascar, praline și boabe de tonka creează semnături olfactive polivalente.",
    "about.housesSec": "CASE DE PARFUMURI SELECTATE",
